-- docs.apply_heading v2: shortcut styles, text types, then a bounded poll proves the exact text in the outline; the menu fallback walks Format with exact finds when the poll exhausts.
-- No text means nothing to prove.

select public.opera_register_workflow(
  'docs.apply_heading',
  $wf${"steps":[{"id":"styleBurst","type":"command","method":"browser.burst","params":{"tabId":{"$ref":"input.tabId"},"steps":[{"action":"key","key":{"$ref":"input.level"},"modifiers":["control","alt"]}]}},{"id":"writeBlock","type":"if","condition":{"op":"exists","left":{"$ref":"input.text"}},"then":[{"id":"typeBurst","type":"command","method":"browser.burst","params":{"tabId":{"$ref":"input.tabId"},"steps":[{"action":"key","text":{"$ref":"input.text"}}]}},{"id":"breakBurst","type":"command","method":"browser.burst","params":{"tabId":{"$ref":"input.tabId"},"steps":[{"action":"key","text":"\n"}]}},{"id":"resetBurst","type":"command","method":"browser.burst","params":{"tabId":{"$ref":"input.tabId"},"steps":[{"action":"key","key":"0","modifiers":["control","alt"]}]}}],"else":[]},{"id":"proveBlock","type":"if","condition":{"op":"exists","left":{"$ref":"input.text"}},"then":[{"id":"outlinePoll","type":"repeat","maxIterations":12,"failOnLimit":false,"steps":[{"id":"outlineRead","type":"command","method":"page.read","params":{"tabId":{"$ref":"input.tabId"},"limit":2000,"maxElements":10}}],"until":{"op":"contains","left":{"$ref":"steps.outlineRead.result.page.text"},"right":{"$ref":"input.text"}}},{"id":"appliedCheck","type":"if","condition":{"op":"contains","left":{"$ref":"steps.outlineRead.result.page.text"},"right":{"$ref":"input.text"}},"then":[{"name":"applied","type":"set","value":true}],"else":[{"id":"backUp","type":"command","method":"browser.burst","params":{"tabId":{"$ref":"input.tabId"},"steps":[{"action":"key","key":"ArrowUp"}]}},{"id":"menuFallback","type":"command","method":"browser.burst","params":{"tabId":{"$ref":"input.tabId"},"steps":[{"action":"find","text":"Format","exact":true},{"action":"click","refFromStep":0}]}},{"id":"styleHover","type":"command","method":"browser.burst","params":{"tabId":{"$ref":"input.tabId"},"steps":[{"action":"find","text":"Paragraph styles","exact":true},{"action":"hover","refFromStep":0}]}},{"id":"levelPick","type":"command","method":"browser.burst","params":{"tabId":{"$ref":"input.tabId"},"steps":[{"action":"find","text":{"$concat":["Heading ",{"$ref":"input.level"}]},"exact":true},{"action":"click","refFromStep":0}]}},{"id":"cursorDown","type":"command","method":"browser.burst","params":{"tabId":{"$ref":"input.tabId"},"steps":[{"action":"key","key":"ArrowDown"}]}},{"id":"outlinePoll2","type":"repeat","maxIterations":12,"failOnLimit":false,"steps":[{"id":"outlineRead2","type":"command","method":"page.read","params":{"tabId":{"$ref":"input.tabId"},"limit":2000,"maxElements":10}}],"until":{"op":"contains","left":{"$ref":"steps.outlineRead2.result.page.text"},"right":{"$ref":"input.text"}}},{"id":"appliedAgain","type":"if","condition":{"op":"contains","left":{"$ref":"steps.outlineRead2.result.page.text"},"right":{"$ref":"input.text"}},"then":[{"name":"applied","type":"set","value":true}],"else":[{"name":"applied","type":"set","value":false}]}]}],"else":[{"name":"applied","type":"set","value":false}]}],"output":{"applied":{"$ref":"vars.applied"},"style":{"$concat":["heading",{"$ref":"input.level"}]}}}$wf$,
  'Style a heading by shortcut, prove the exact text in the outline, menu fallback with exact finds.',
  true
);
